function fmtLine(s, o = {}) { return String(s).replace(/\{up\}/g, UP).replace(/\{op\}/g, OP()).replace(/\{f\}/g, o.f ?? '').replace(/\{apt\}/g, o.apt ?? '').replace(/\{g\}/g, o.g ?? '').replace(/\{q\}/g, o.q ?? ''); }
// деньги: 780 000 ₸ → «780 тыс. ₸», 1 560 000 → «1,56 млн ₸»
function money(n) { n = Math.round(n || 0); const neg = n < 0 ? '−' : ''; n = Math.abs(n);
  if (n >= 1e6) return neg + (n / 1e6).toFixed(n % 1e6 === 0 ? 0 : 2).replace(/0$/, '').replace('.', ',') + (LANG === 'kz' ? ' млн ₸' : ' млн ₸');
  if (n >= 1000) return neg + Math.round(n / 1000) + (LANG === 'kz' ? ' мың ₸' : ' тыс. ₸');
  return neg + n + ' ₸'; }
const LEVELS = TOUR_DEFS.map((d, i) => ({
  ...d, id: 'L' + (i + 1), n: i + 1, problem: d.problem || null, scen: SCEN_KEY[d.code],
  floors: HOUSE.floors, perFloor: HOUSE.perFloor, heroApt: HOUSE.heroApt,
  start: 0, secPerMin: 3, days: 60,
  awayShare: .22 + i * .015,
  talkerFloor: [3, 5, 4, 9, 2, 6, 8][i], helperAfter: 3, helperFloor: [10, 11, 12, 9, 11, 12, 10][i],
  income: INCOME[i],
  // состав дома на 100 квартир (утверждено): новосёлок 6, «нехорошая» 1, не собственников 6, арендаторов 8, остальное — характеры
  mix: (() => {
    const total = APTS - 1, h = d.hard, out = [];
    const fixed = { novosel: 6, shady: 1, notowner: 6, renter: 8 };
    for (const a in fixed) for (let k = 0; k < fixed[a]; k++) out.push(a);
    const share = { apa: .1, mom: .14, business: .11, grump: .08 + h * .2, night: .09 + h * .1, ata: .07, teacher: .06, dad: .11, it: .1 };
    const rest = total - out.length, sum = Object.values(share).reduce((a, b) => a + b, 0);
    for (const a in share) for (let k = 0; k < Math.round(share[a] / sum * rest); k++) out.push(a);
    while (out.length < total) out.push('mom'); return out.slice(0, total);
  })(),
}));
/* Правила доступа — общие для игры и сервера: H = { won: [...туры], fixed: [...ремонты] } */
function tourOpen(t, H) {
  const i = t.n - 1;
  if (i > 0 && !H.won.includes(LEVELS[i - 1].id)) return { ok: false, why: 'prev', need: LEVELS[i - 1] };
  return { ok: true };
}
// можно ли чинить: обычный ремонт — после избрания председателем (тур 2); решения собраний (летник, вышка, лифт, крыша) появляются сами
function canFix(p, H) {
  if (H.fixed.includes(p.id)) return { ok: false, why: 'done' };
  if (p.kind === 'construction') return { ok: false, why: 'vote', tour: TOURS[p.tour] };
  if (!H.won.includes('L2')) return { ok: false, why: 'chair', tour: TOURS.L2 };
  return { ok: true };
}
// итог голосования по правилам тура: yes — «за», no — «против», ab — «воздержался» (идёт в кворум)
function ruleText(t) { return fmtLine(L(t.ruleText), { g: t.goal, q: t.quorum || '' }); }
function tourTitle(t) { return fmtLine(L(t.title)); }
function voteOutcome(t, yes, no, ab = 0) {
  const turnout = yes + no + ab;
  if (t.rule === 'quorum') { const need = Math.max(t.goal, Math.floor(turnout / 2) + 1); return { ok: turnout >= t.quorum && yes >= need, need, turnout }; }
  return { ok: yes >= t.goal, need: t.goal, turnout };
}
const TOURS = Object.fromEntries(LEVELS.map(l => [l.id, l]));

